package com.cowave.search.config

import org.springframework.boot.context.properties.ConfigurationProperties
import org.springframework.context.annotation.Configuration

@Configuration
@ConfigurationProperties(prefix = "dictionary")
class DictionaryConfig {
    var outputPath: String = "/data/dictionary"
}

package com.cowave.search

import org.springframework.boot.autoconfigure.SpringBootApplication
import org.springframework.boot.runApplication

@SpringBootApplication
class SearchAdminServerApplication

fun main(args: Array<String>) {
    runApplication<SearchAdminServerApplication>(*args)
}

package com.cowave.search.controller

import com.cowave.search.controller.dto.CompileResult
import com.cowave.search.controller.dto.CreateDictionaryRequest
import com.cowave.search.controller.dto.UpdateDictionaryRequest
import com.cowave.search.domain.DictionaryWithId
import com.cowave.search.domain.Type
import com.cowave.search.service.DictionaryService
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/api/v1/dictionary")
class DictionaryController(
    private val dictionaryService: DictionaryService,
) {
    @GetMapping("/{type}")
    fun getByType(
        @PathVariable type: Type,
        @RequestParam(defaultValue = "0") page: Int,
        @RequestParam(defaultValue = "20") size: Int,
    ): List<DictionaryWithId> = dictionaryService.getByType(type, page, size)

    @GetMapping("/{type}/search")
    fun search(
        @PathVariable type: Type,
        @RequestParam word: String,
        @RequestParam(defaultValue = "true") isMatch: Boolean,
    ): List<DictionaryWithId> = dictionaryService.searchByWord(word, type, isMatch)

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(
        @RequestBody request: CreateDictionaryRequest,
    ) {
        dictionaryService.create(request.keyword, request.type, request.value)
    }

    @PutMapping("/{id}")
    fun update(
        @PathVariable id: String,
        @RequestBody request: UpdateDictionaryRequest,
    ) {
        dictionaryService.update(id, request.keyword, request.type, request.value)
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(
        @PathVariable id: String,
    ) {
        dictionaryService.delete(id)
    }

    @PostMapping("/compile/{type}")
    fun compile(
        @PathVariable type: Type,
    ): CompileResult = dictionaryService.compile(type)

    @PostMapping("/compile")
    fun compileAll(): List<CompileResult> = dictionaryService.compileAll()
}

package com.cowave.search.service

import com.cowave.search.controller.dto.CompileResult
import com.cowave.search.domain.DictionaryWithId
import com.cowave.search.domain.Type
import com.cowave.search.utils.DictionaryBinaryCompile
import org.springframework.stereotype.Service

@Service
class DictionaryService(
    val dictionaryRepository: DictionaryRepository,
    val dictionaryBinaryCompile: DictionaryBinaryCompile,
) {
    fun getByType(
        type: Type,
        page: Int,
        size: Int,
    ): List<DictionaryWithId> = dictionaryRepository.findAllWithPageByType(type, page, size)

    fun searchByWord(
        word: String,
        type: Type,
        isMatch: Boolean,
    ): List<DictionaryWithId> = dictionaryRepository.findByWordAndType(word, type, isMatch)

    fun create(
        keyword: String?,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.insert(keyword, type, value)
    }

    fun update(
        id: String,
        keyword: String,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.update(id, keyword, type, value)
    }

    fun delete(id: String) {
        dictionaryRepository.delete(id)
    }

    fun compile(type: Type): CompileResult {
        val dictionaries = dictionaryRepository.findAllByType(type)
        val pairs = dictionaries.map { it.keyword to it.value }
        val outputFile = dictionaryBinaryCompile.compileToConfiguredPath(pairs, type)

        return CompileResult(
            type = type,
            count = dictionaries.size,
            filePath = outputFile.absolutePath,
            fileSize = outputFile.length(),
        )
    }

    fun compileAll(): List<CompileResult> = Type.entries.map { compile(it) }
}
